  | ModelStatusModelStageStable -- ^ Models in this stage are considered stable and ready for production use.
  | ModelStatusModelStageLegacy -- ^ If the model is on this stage, it means that this model is on the path to deprecation in near future. Only existing customers can use this model.
  | ModelStatusModelStageDeprecated -- ^ Models in this stage are deprecated. These models cannot be used.
  | ModelStatusModelStageRetired -- ^ Models in this stage are retired. These models cannot be used.
  | ModelStatusModelStageUnknown Text -- ^ A value this module does not know about.
  deriving (Show, Eq, Generic)

instance FromJSON ModelStatusModelStage where
  parseJSON = withText "ModelStatusModelStage" $ \t -> pure $ case t of
