-- | A datatype containing media that is part of a multi-part \`Content\` message. A \`Part\` consists of data which has an associated datatype. A \`Part\` can only contain one of the accepted types in \`Part.data\`. A \`Part\` must have a fixed IANA MIME type identifying the type and subtype of the media if the \`inline_data\` field is filled with raw bytes.
data Part = Part
  { partAudioTranscription :: !(Maybe AudioTranscription)
    -- ^ Optional. Audio (input or output) transcription. This is only set when this Part contains audio data.
  , partCodeExecutionResult :: !(Maybe CodeExecutionResult)
    -- ^ Result of executing the \`ExecutableCode\`.
  , partExecutableCode :: !(Maybe ExecutableCode)
    -- ^ Code generated by the model that is meant to be executed.
  , partFileData :: !(Maybe FileData)
    -- ^ URI based data.
  , partFunctionCall :: !(Maybe FunctionCall)
    -- ^ A predicted \`FunctionCall\` returned from the model that contains a string representing the \`FunctionDeclaration.name\` with the arguments and their values.
  , partFunctionResponse :: !(Maybe FunctionResponse)
    -- ^ The result output of a \`FunctionCall\` that contains a string representing the \`FunctionDeclaration.name\` and a structured JSON object containing any output from the function is used as context to the model.
  , partInlineData :: !(Maybe Blob)
    -- ^ Inline media bytes.
  , partMediaProcessing :: !(Maybe PartMediaProcessing)
    -- ^ Optional. How the model processes this part\'s media for understanding. Only meaningful for video parts (\`inline_data\` or \`file_data\` with video mime). Non-video parts ignore this field.
  , partMediaResolution :: !(Maybe V1mainMediaResolution)
    -- ^ Optional. Media resolution for the input media.
  , partPartMetadata :: !(Object)
    -- ^ Custom metadata associated with the Part. Agents using genai.Part as content representation may need to keep track of the additional information. For example it can be name of a file\/source from which the Part originates or a way to multiplex multiple Part streams.
  , partText :: !(Maybe Text)
    -- ^ Inline text.
  , partThought :: !(Maybe Bool)
    -- ^ Optional. Indicates if the part is thought from the model.
  , partThoughtSignature :: !(Maybe Base64Bytes)
    -- ^ Optional. An opaque signature for the thought so it can be reused in subsequent requests.
  , partToolCall :: !(Maybe ToolCall)
    -- ^ Server-side tool call. This field is populated when the model predicts a tool invocation that should be executed on the server. The client is expected to echo this message back to the API.
  , partToolResponse :: !(Maybe ToolResponse)
    -- ^ The output from a server-side \`ToolCall\` execution. This field is populated by the client with the results of executing the corresponding \`ToolCall\`.
  , partVideoMetadata :: !(Maybe VideoMetadata)
    -- ^ Optional. Video metadata. The metadata should only be specified while the video data is presented in inline_data or file_data.
  }
  deriving (Show, Eq, Generic)

-- | Required fields positional (alphabetical); everything else defaulted.
mkPart :: Part
mkPart =
  Part
    { partAudioTranscription = Nothing
    , partCodeExecutionResult = Nothing
    , partExecutableCode = Nothing
    , partFileData = Nothing
    , partFunctionCall = Nothing
    , partFunctionResponse = Nothing
    , partInlineData = Nothing
    , partMediaProcessing = Nothing
    , partMediaResolution = Nothing
    , partPartMetadata = mempty
    , partText = Nothing
    , partThought = Nothing
    , partThoughtSignature = Nothing
    , partToolCall = Nothing
    , partToolResponse = Nothing
    , partVideoMetadata = Nothing
    }

instance FromJSON Part where
  parseJSON = withObject "Part" $ \o ->
    Part
      <$> (o .:? "audioTranscription")
      <*> (o .:? "codeExecutionResult")
      <*> (o .:? "executableCode")
      <*> (o .:? "fileData")
      <*> (o .:? "functionCall")
      <*> (o .:? "functionResponse")
      <*> (o .:? "inlineData")
      <*> (o .:? "mediaProcessing")
      <*> (o .:? "mediaResolution")
      <*> (o .:? "partMetadata" .!= mempty)
      <*> (o .:? "text")
      <*> (o .:? "thought")
      <*> (o .:? "thoughtSignature")
      <*> (o .:? "toolCall")
      <*> (o .:? "toolResponse")
      <*> (o .:? "videoMetadata")

instance ToJSON Part where
  toJSON Part{..} = object $ catMaybes
    [ ("audioTranscription" .=) <$> partAudioTranscription
    , ("codeExecutionResult" .=) <$> partCodeExecutionResult
    , ("executableCode" .=) <$> partExecutableCode
    , ("fileData" .=) <$> partFileData
    , ("functionCall" .=) <$> partFunctionCall
    , ("functionResponse" .=) <$> partFunctionResponse
    , ("inlineData" .=) <$> partInlineData
    , ("mediaProcessing" .=) <$> partMediaProcessing
    , ("mediaResolution" .=) <$> partMediaResolution
    , if null partPartMetadata then Nothing else Just ("partMetadata" .= partPartMetadata)
    , ("text" .=) <$> partText
    , ("thought" .=) <$> partThought
    , ("thoughtSignature" .=) <$> partThoughtSignature
    , ("toolCall" .=) <$> partToolCall
    , ("toolResponse" .=) <$> partToolResponse
    , ("videoMetadata" .=) <$> partVideoMetadata
    ]

