    "HARM_CATEGORY_TOXICITY" -> SafetyRatingCategoryHarmCategoryToxicity
    "HARM_CATEGORY_VIOLENCE" -> SafetyRatingCategoryHarmCategoryViolence
    "HARM_CATEGORY_SEXUAL" -> SafetyRatingCategoryHarmCategorySexual
    "HARM_CATEGORY_MEDICAL" -> SafetyRatingCategoryHarmCategoryMedical
