-- | Metadata on the generation request\'s token usage.
data UsageMetadata = UsageMetadata
  { usageMetadataCacheTokensDetails :: !([ModalityTokenCount])
    -- ^ Output only. List of modalities of the cached content in the request input.
  , usageMetadataCachedContentTokenCount :: !(Int)
    -- ^ Number of tokens in the cached part of the prompt (the cached content)
  , usageMetadataCandidatesTokenCount :: !(Int)
    -- ^ Total number of tokens across all the generated response candidates.
  , usageMetadataCandidatesTokensDetails :: !([ModalityTokenCount])
    -- ^ Output only. List of modalities that were returned in the response.
  , usageMetadataPromptTokenCount :: !(Int)
    -- ^ Number of tokens in the prompt. When \`cached_content\` is set, this is still the total effective prompt size meaning this includes the number of tokens in the cached content.
  , usageMetadataPromptTokensDetails :: !([ModalityTokenCount])
    -- ^ Output only. List of modalities that were processed in the request input.
  , usageMetadataServiceTier :: !(UsageMetadataServiceTier)
    -- ^ Output only. Service tier of the request.
  , usageMetadataThoughtsTokenCount :: !(Int)
    -- ^ Output only. Number of tokens of thoughts for thinking models.
  , usageMetadataToolUsePromptTokenCount :: !(Int)
    -- ^ Output only. Number of tokens present in tool-use prompt(s).
  , usageMetadataToolUsePromptTokensDetails :: !([ModalityTokenCount])
    -- ^ Output only. List of modalities that were processed for tool-use request inputs.
  , usageMetadataTotalTokenCount :: !(Int)
    -- ^ Total token count for the generation request (prompt + thoughts + response candidates).
  }
  deriving (Show, Eq, Generic)

-- | Required fields positional (alphabetical); everything else defaulted.
mkUsageMetadata :: UsageMetadata
mkUsageMetadata =
  UsageMetadata
    { usageMetadataCacheTokensDetails = mempty
    , usageMetadataCachedContentTokenCount = 0
    , usageMetadataCandidatesTokenCount = 0
    , usageMetadataCandidatesTokensDetails = mempty
    , usageMetadataPromptTokenCount = 0
    , usageMetadataPromptTokensDetails = mempty
    , usageMetadataServiceTier = UsageMetadataServiceTierUnspecified
    , usageMetadataThoughtsTokenCount = 0
    , usageMetadataToolUsePromptTokenCount = 0
    , usageMetadataToolUsePromptTokensDetails = mempty
    , usageMetadataTotalTokenCount = 0
    }

instance FromJSON UsageMetadata where
  parseJSON = withObject "UsageMetadata" $ \o ->
    UsageMetadata
      <$> (o .:? "cacheTokensDetails" .!= mempty)
      <*> (o .:? "cachedContentTokenCount" .!= 0)
      <*> (o .:? "candidatesTokenCount" .!= 0)
      <*> (o .:? "candidatesTokensDetails" .!= mempty)
      <*> (o .:? "promptTokenCount" .!= 0)
      <*> (o .:? "promptTokensDetails" .!= mempty)
      <*> (o .:? "serviceTier" .!= UsageMetadataServiceTierUnspecified)
      <*> (o .:? "thoughtsTokenCount" .!= 0)
      <*> (o .:? "toolUsePromptTokenCount" .!= 0)
      <*> (o .:? "toolUsePromptTokensDetails" .!= mempty)
      <*> (o .:? "totalTokenCount" .!= 0)

instance ToJSON UsageMetadata where
  toJSON UsageMetadata{..} = object $ catMaybes
    [ if null usageMetadataCacheTokensDetails then Nothing else Just ("cacheTokensDetails" .= usageMetadataCacheTokensDetails)
    , Just ("cachedContentTokenCount" .= usageMetadataCachedContentTokenCount)
    , Just ("candidatesTokenCount" .= usageMetadataCandidatesTokenCount)
    , if null usageMetadataCandidatesTokensDetails then Nothing else Just ("candidatesTokensDetails" .= usageMetadataCandidatesTokensDetails)
    , Just ("promptTokenCount" .= usageMetadataPromptTokenCount)
    , if null usageMetadataPromptTokensDetails then Nothing else Just ("promptTokensDetails" .= usageMetadataPromptTokensDetails)
    , Just ("serviceTier" .= usageMetadataServiceTier)
    , Just ("thoughtsTokenCount" .= usageMetadataThoughtsTokenCount)
    , Just ("toolUsePromptTokenCount" .= usageMetadataToolUsePromptTokenCount)
    , if null usageMetadataToolUsePromptTokensDetails then Nothing else Just ("toolUsePromptTokensDetails" .= usageMetadataToolUsePromptTokensDetails)
    , Just ("totalTokenCount" .= usageMetadataTotalTokenCount)
    ]

-- | The tokenization quality used for given media. for Gemini API support .
data V1mainMediaResolutionLevel
  = V1mainMediaResolutionLevelMediaResolutionUnspecified -- ^ Media resolution has not been set.
  | V1mainMediaResolutionLevelMediaResolutionLow -- ^ Media resolution set to low.
  | V1mainMediaResolutionLevelMediaResolutionMedium -- ^ Media resolution set to medium.
  | V1mainMediaResolutionLevelMediaResolutionHigh -- ^ Media resolution set to high.
  | V1mainMediaResolutionLevelMediaResolutionUltraHigh -- ^ Media resolution set to ultra high.
  | V1mainMediaResolutionLevelUnknown Text -- ^ A value this module does not know about.
  deriving (Show, Eq, Generic)

instance FromJSON V1mainMediaResolutionLevel where
  parseJSON = withText "V1mainMediaResolutionLevel" $ \t -> pure $ case t of
    "MEDIA_RESOLUTION_UNSPECIFIED" -> V1mainMediaResolutionLevelMediaResolutionUnspecified
    "MEDIA_RESOLUTION_LOW" -> V1mainMediaResolutionLevelMediaResolutionLow
    "MEDIA_RESOLUTION_MEDIUM" -> V1mainMediaResolutionLevelMediaResolutionMedium
    "MEDIA_RESOLUTION_HIGH" -> V1mainMediaResolutionLevelMediaResolutionHigh
    "MEDIA_RESOLUTION_ULTRA_HIGH" -> V1mainMediaResolutionLevelMediaResolutionUltraHigh
    other -> V1mainMediaResolutionLevelUnknown other

instance ToJSON V1mainMediaResolutionLevel where
  toJSON x = String $ case x of
    V1mainMediaResolutionLevelMediaResolutionUnspecified -> "MEDIA_RESOLUTION_UNSPECIFIED"
    V1mainMediaResolutionLevelMediaResolutionLow -> "MEDIA_RESOLUTION_LOW"
    V1mainMediaResolutionLevelMediaResolutionMedium -> "MEDIA_RESOLUTION_MEDIUM"
    V1mainMediaResolutionLevelMediaResolutionHigh -> "MEDIA_RESOLUTION_HIGH"
    V1mainMediaResolutionLevelMediaResolutionUltraHigh -> "MEDIA_RESOLUTION_ULTRA_HIGH"
    V1mainMediaResolutionLevelUnknown other -> other

-- | Media resolution for tokenization.
data V1mainMediaResolution = V1mainMediaResolution
  { v1mainMediaResolutionLevel :: !(Maybe V1mainMediaResolutionLevel)
    -- ^ The tokenization quality used for given media. for Gemini API support .
  }
  deriving (Show, Eq, Generic)

-- | Required fields positional (alphabetical); everything else defaulted.
mkV1mainMediaResolution :: V1mainMediaResolution
