  V1mainMediaResolution
    { v1mainMediaResolutionLevel = Nothing
    }

instance FromJSON V1mainMediaResolution where
  parseJSON = withObject "V1mainMediaResolution" $ \o ->
    V1mainMediaResolution
      <$> (o .:? "level")

instance ToJSON V1mainMediaResolution where
  toJSON V1mainMediaResolution{..} = object $ catMaybes
    [ ("level" .=) <$> v1mainMediaResolutionLevel
    ]

